def predict_changes(threshold_grid, frame_val):
    """Predict all gaps for both row and col filling"""
    rows = len(threshold_grid)
    cols = len(threshold_grid[0])
    all_frame_rows = set()
    all_frame_cols = set()

    # Find all rows with frame
    for r in range(rows):
        for c in range(cols):
            if threshold_grid[r][c] == frame_val:
                all_frame_rows.add(r)

    # Find all cols with frame
    for c in range(cols):
        for r in range(rows):
            if threshold_grid[r][c] == frame_val:
                all_frame_cols.add(c)

    predicted = set()

    # Row gaps: for each row with frame, fill gap cols within min-max frame cols for that row
    for r in all_frame_rows:
        row_frame_cols = {c for c in range(cols) if threshold_grid[r][c] == frame_val}
        if row_frame_cols:
            min_fc = min(row_frame_cols)
            max_fc = max(row_frame_cols)
            for c in range(min_fc, max_fc + 1):
                if c not in row_frame_cols:
                    predicted.add((r, c))

    # Col gaps: for each col with frame, fill gap rows within min-max frame rows for that col
    for c in all_frame_cols:
        col_frame_rows = {r for r in range(rows) if threshold_grid[r][c] == frame_val}
        if col_frame_rows:
            min_fr = min(col_frame_rows)
            max_fr = max(col_frame_rows)
            for r in range(min_fr, max_fr + 1):
                if r not in col_frame_rows:
                    predicted.add((r, c))

    return predicted

