def apply_unique_fill(grid, frame_val):
    """Apply filling rule: for lines with unique frame count, fill gaps with 2"""
    rows = len(grid)
    cols = len(grid[0])
    prediction = set()

    # Count frame cells per row and col
    row_counts = {r: sum(1 for c in range(cols) if grid[r][c] == frame_val) for r in range(rows)}
    col_counts = {c: sum(1 for r in range(rows) if grid[r][c] == frame_val) for c in range(cols)}

    from collections import Counter
    row_unique_counts = Counter(row_counts.values())
    col_unique_counts = Counter(col_counts.values())

    # Find truly unique lines (count appears exactly once)
    unique_row_indices = {r for r, cnt in row_counts.items() if row_unique_counts[cnt] == 1}
    unique_col_indices = {c for c, cnt in col_counts.items() if col_unique_counts[cnt] == 1}

    # For each unique row, fill gaps in horizontal span
    for r in unique_row_indices:
        frame_cols_in_row = [c for c in range(cols) if grid[r][c] == frame_val]
        if frame_cols_in_row:
            min_fc = min(frame_cols_in_row)
            max_fc = max(frame_cols_in_row)
            for c in range(min_fc, max_fc + 1):
                if c not in frame_cols_in_row:
                    prediction.add((r, c))

    # For each unique col, fill gaps in vertical span
    for c in unique_col_indices:
        frame_rows_in_col = [r for r in range(rows) if grid[r][c] == frame_val]
        if frame_rows_in_col:
            min_fr = min(frame_rows_in_col)
            max_fr = max(frame_rows_in_col)
            for r in range(min_fr, max_fr + 1):
                if r not in frame_rows_in_col:
                    prediction.add((r, c))

    return prediction, row_counts, col_counts, unique_row_indices, unique_col_indices

def verify_all(demo_name, grid_in, grid_out, frame_val, dims):
    actual = {(r,c) for r in range(dims[0]) for c in range(dims[1]) if grid_in[r][c] != grid_out[r][c]}
    pred, row_counts, col_counts, unique_rows, unique_cols = apply_unique_fill(grid_in, frame_val)
    match = pred == actual
    missing = pred - actual
    extra = actual - pred

    print(f"\n{demo_name}: {'✓' if match else '✗'}")
    if not match:
        print(f"  Unique rows: {sorted(unique_rows)}")
        print(f"  Unique cols: {sorted(unique_cols)}")
        print(f"  Row counts: {dict(row_counts)}")
        print(f"  Col counts: {dict(col_counts)}")
        print(f"  Predicted ({len(pred)}): {sorted(pred)[:20]}...{'...' if len(pred) > 20 else ''}")
        print(f"  Actual ({len(actual)}):   {sorted(actual)}")
        if missing:
            print(f"  Missing: {missing}")
        if extra:
            print(f"  Extra:   {extra}")
    return match

