def frame_gaps(grid, frame_val):
    """Find row gaps (positions within min-max cols that aren't frame)
       and col gaps. Return all changed positions."""
    rows = len(grid)
    cols = len(grid[0])
    frame_rows = set()
    frame_cols = set()
    # Find min/max bounding box
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == frame_val:
                frame_rows.add(r)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == frame_val:
                frame_cols.add(c)

    if not frame_rows:
        return set()

    min_r = min(frame_rows)
    max_r = max(frame_rows)
    min_c = min(frame_cols)
    max_c = max(frame_cols)

    # Row gaps: in each frame row, which cols are not frame?
    row_changes = set()
    for r in sorted(frame_rows):
        row_frame_cols = set(c for c in range(cols) if grid[r][c] == frame_val)
        # The "gap" cols are those between min/max frame cols on this row
        if row_frame_cols:
            min_fc = min(row_frame_cols)
            max_fc = max(row_frame_cols)
            for c in range(min_fc, max_fc + 1):
                if c not in row_frame_cols:
                    row_changes.add((r, c))

    # Col gaps: similar but vertical
    col_changes = set()
    for c in sorted(frame_cols):
        col_frame_rows = set(r for r in range(rows) if grid[r][c] == frame_val)
        if col_frame_rows:
            min_fr = min(col_frame_rows)
            max_fr = max(col_frame_rows)
            for r in range(min_fr, max_fr + 1):
                if r not in col_frame_rows:
                    col_changes.add((r, c))

    return row_changes | col_changes

